     1→// Clearfix
     2→@mixin clearfix() {
     3→  &::after,
     4→  ::before {
     5→    content: "";
     6→    display: table;
     7→    clear: both;
     8→  }
     9→}
    10→
    11→// Reset list
    12→@mixin list-reset() {
    13→  list-style-type: none;
    14→  margin: 0;
    15→  padding: 0;
    16→}
    17→
    18→// Screen reader text
    19→@mixin screen-reader() {
